//! Explicit shared definitions, ordered clip groups and final timeline grading.
use std::collections::{BTreeMap,BTreeSet};use serde::{Serialize,Deserialize};use super::node_graph::Graph;use crate::{model::Project,effects::Frame};
#[derive(Clone,Debug,Default,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Scopes{#[serde(default)]pub graphs:BTreeMap<String,Graph>,#[serde(default)]pub clip_bindings:BTreeMap<String,Vec<String>>,#[serde(default)]pub groups:Vec<Group>,#[serde(default)]pub timeline:Vec<String>}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Group{pub id:String,pub clips:Vec<String>,pub graphs:Vec<String>,#[serde(default)]pub bypass:bool}
impl Scopes{
 pub fn copy_binding(&mut self,old:&str,new:&str){if let Some(refs)=self.clip_bindings.get(old).cloned(){self.clip_bindings.insert(new.into(),refs);}for g in &mut self.groups{if g.clips.iter().any(|c|c==old)&&!g.clips.iter().any(|c|c==new){g.clips.push(new.into());}}}
 pub fn subset(&self,tracks:&[crate::model::Track])->Self{let ids:BTreeSet<_>=crate::render::flat_clips(tracks,0.).iter().map(|c|c.id.clone()).collect();let mut s=self.clone();s.timeline.clear();s.clip_bindings.retain(|c,_|ids.contains(c));for g in &mut s.groups{g.clips.retain(|c|ids.contains(c));}s}

 pub fn validate(&self,p:&Project)->Result<(),String>{if self.graphs.len()>128||self.groups.len()>128||self.timeline.len()>16{return Err("max128sharedgraphs/groups,16timelinegrades".into())}let clips: BTreeSet<_>=crate::render::flat_clips(&p.tracks,0.).iter().map(|c|c.id.clone()).collect();let refs=|list:&Vec<String>|->Result<(),String>{if list.len()>16||list.iter().collect::<BTreeSet<_>>().len()!=list.len(){return Err("max16unique ordered grade references".into())}for id in list{if !self.graphs.contains_key(id){return Err(format!("missing shared graph {id}"))}}Ok(())};for(id,g)in &self.graphs{if id.is_empty()||id.len()>128{return Err("invalid shared graph id".into())}g.validate_project(p)?;}for(c,g)in &self.clip_bindings{if !clips.contains(c){return Err(format!("missing bound clip {c}"))}refs(g)?;}let mut ids=BTreeSet::new();for group in &self.groups{if group.id.is_empty()||!ids.insert(&group.id)||group.clips.iter().collect::<BTreeSet<_>>().len()!=group.clips.len(){return Err("invalid/duplicate grade group".into())}for c in &group.clips{if !clips.contains(c){return Err(format!("missing group clip {c}"))}}refs(&group.graphs)?;}refs(&self.timeline)}
 pub fn clip_has_grade(&self,id:&str)->bool{self.clip_bindings.get(id).map(|v|!v.is_empty()).unwrap_or(false)||self.groups.iter().any(|g|!g.bypass&&g.clips.iter().any(|c|c==id)&&!g.graphs.is_empty())}
 pub fn apply_clip(&self,p:&Project,id:&str,f:&mut Frame,t:f64,seed:u64)->Result<(),String>{if let Some(list)=self.clip_bindings.get(id){self.apply_list(p,list,f,t,seed)?;}for g in &self.groups{if !g.bypass&&g.clips.iter().any(|c|c==id){self.apply_list(p,&g.graphs,f,t,seed)?}}Ok(())}
 pub fn apply_list(&self,p:&Project,list:&[String],f:&mut Frame,t:f64,seed:u64)->Result<(),String>{for id in list{let g=self.graphs.get(id).ok_or_else(||format!("missing shared graph {id}"))?;g.validate_project(p)?;g.apply(f,t,seed,p.fps)?;}Ok(())}
}
